//! 🏦️ Finite fixture Source ownership, physical stock and original Work persist through Pending.
pub use semio_framework_value_control_contract::*;
/// 🪙️ Issues the one-item grant that exactly covers a quoted retirement demand; every test funds a quoted step with it.
pub fn demand_grant(demand:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth}}
pub struct WorkLoan<'a>{remaining:&'a u128,maximum:u64}
impl<'a> WorkLoan<'a>{pub fn new(remaining:&'a u128,maximum:u64)->Self{Self{remaining,maximum}}pub fn original_remaining(&self)->&'a u128{self.remaining}pub fn issued_maximum(&self)->u64{self.maximum}pub fn maximum(&self)->u64{self.maximum.min(u64::try_from(*self.remaining).expect("original fixture work remains within its u64-issued stock"))}}
pub struct Wallet{left:RetainedCloneGrant,work:u128}
impl Wallet{
 /// 🪙️ Seats one explicit finite native stock without allocating a profile or issuing another Source.
 pub const fn new(grant:RetainedCloneGrant,work:u64)->Self{Self{left:grant,work:work as u128}}
 pub fn remaining(&self)->RetainedCloneGrant{self.left}
 /// 🧮️ Derives a turn grant from the finite stock left: every currency of the request clamped to what remains, so callers never name a literal above the stock.
 pub fn within(&self,requested:RetainedCloneGrant)->RetainedCloneGrant{let left=self.left;RetainedCloneGrant{maximum_items:requested.maximum_items.min(left.maximum_items),maximum_copy_bytes:requested.maximum_copy_bytes.min(left.maximum_copy_bytes),maximum_capacity_bytes:requested.maximum_capacity_bytes.min(left.maximum_capacity_bytes),maximum_release_bytes:requested.maximum_release_bytes.min(left.maximum_release_bytes),maximum_depth:requested.maximum_depth.min(left.maximum_depth)}}
 pub fn original_work(&self)->&u128{&self.work}
 pub fn remaining_work(&self)->u64{u64::try_from(self.work).expect("original fixture work remains within its u64-issued stock")}
 pub fn work_loan(&self,maximum:u64)->WorkLoan<'_>{WorkLoan::new(&self.work,maximum)}
 pub fn from_profile(profile:&serde_json::Value)->Self{Self::new(RetainedCloneGrant{maximum_items:profile["items"].as_u64().unwrap().try_into().unwrap(),maximum_copy_bytes:profile["copyBytes"].as_u64().unwrap().try_into().unwrap(),maximum_capacity_bytes:profile["capacityBytes"].as_u64().unwrap().try_into().unwrap(),maximum_release_bytes:profile["releaseBytes"].as_u64().unwrap().try_into().unwrap(),maximum_depth:profile["depth"].as_u64().unwrap().try_into().unwrap()},profile["fuel"].as_u64().unwrap())}
 pub fn loan(&self,items:usize,copy:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:if self.work==0{0}else{self.left.maximum_items.min(items)},maximum_copy_bytes:self.left.maximum_copy_bytes.min(copy),..self.left}}
 pub fn post(&mut self,p:RetainedCloneProgress,work:u128,g:RetainedCloneGrant,heap:(usize,usize)){assert!(p.fits(g),"posted {p:?} exceeds its turn grant {g:?}");assert!(p.fits(self.left),"posted {p:?} exceeds the remaining stock {:?}",self.left);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.left.maximum_items=self.left.maximum_items.checked_sub(p.copied_items).unwrap();self.left.maximum_copy_bytes=self.left.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.left.maximum_capacity_bytes=self.left.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.left.maximum_release_bytes=self.left.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.work=self.work.checked_sub(work).expect("native fixture depleted its explicit CPU stock");}
}

/// 🏦️ Owns the finite fixture wallet, actual Source dispatch, and original Work authority across turns.
pub struct EffectBank{wallet:Wallet,source:OriginalSourceTurnIssuer,turn:OriginalSourceTurn,work:OriginalWorkAuthority<EffectWorkProducer>,state:OriginalWorkState,action:Option<OriginalWorkActionIdentity>,selected:Option<(RetainedCloneGrant,u64)>,partial:Option<OriginalWorkPartialOutcome>,actual:Option<usize>,marker_pending:bool,admitted:Option<bool>}
struct EffectWorkProducer;
struct EffectWorkContext<'a>{source:&'a OriginalSourceTurnIssuer,turn:&'a OriginalSourceTurn,remaining:&'a u128}
impl OriginalWorkRecipient for EffectWorkProducer{
 type Context<'turn,'source>=EffectWorkContext<'turn> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{c.source.validate(c.turn).map_err(|_|ValueError::invariant("foreign fixture Source turn"))}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity> where 'source:'turn{Some(c.turn.identity())}
 fn admits<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'reply>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'reply> where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|n|u128::from(n)<=*c.remaining)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(c))}
 fn recover_partial<'reply,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(c))}
}
impl EffectBank{
 /// 🪪️ Borrows the genuine retained Source witness without issuing an action or new authority.
 pub fn source_witness(&self)->OriginalSourceTurnWitness<'_>{self.turn.witness()}

 /// 🆕️ Retains one real fixture Source dispatch and the caller-issued finite wallet.
 pub fn new(wallet:Wallet)->Self{let source=OriginalSourceTurnIssuer::new();let turn=source.issue().expect("fixture Source dispatch");Self{wallet,source,turn,work:OriginalWorkAuthority::new(EffectWorkProducer),state:OriginalWorkState::fresh(),action:None,selected:None,partial:None,actual:None,marker_pending:false,admitted:None}}
 /// ⏳️ Observes original action and receipt custody without invoking another producer.
 pub fn has_pending_action(&self)->bool{self.selected.is_some()||self.action.is_some()||self.partial.is_some()||self.marker_pending||self.work.has_live_actions()}
 /// 🛂️ Permits another producer only after the original action, marker and verdict were inspected.
 pub fn is_idle(&self)->bool{!self.has_pending_action()&&self.actual.is_none()&&self.admitted.is_none()}
 pub fn wallet(&self)->&Wallet{&self.wallet}
 /// 📤️ Returns the same finite wallet only after its actual action and receipts have settled.
 pub fn into_wallet(self)->Result<Wallet,Self>{if self.action.is_some()||self.selected.is_some()||self.partial.is_some()||self.actual.is_some()||self.marker_pending||self.admitted.is_some()||self.work.has_live_actions(){return Err(self)}Ok(self.wallet)}
 pub fn loan(&self,items:usize,copy:usize)->RetainedCloneGrant{self.wallet.loan(items,copy)}
 /// 🔍️ Observes the original physical marker without moving it from a pending action.
 pub fn actual(&self)->Option<usize>{self.actual}
 /// ⚖️ Takes the actual original Work admission without replacing a child result.
 pub fn take_admitted(&mut self)->Option<bool>{self.admitted.take()}
 /// 🧵️ Runs or resumes the same Source-bound action and claims its exact performed receipt.
 pub fn run<T,E>(&mut self,grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll<T,E>)->(RetainedWorkPoll<T,E>,Option<usize>){self.run_with_source(grant,maximum,|effect,_|operation(effect))}
 /// 🧵️ Runs one synchronous effect-shaped closer to its completed outcome under the calling turn's own original action.
 pub fn run_outcome<T,E>(&mut self,grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<T,E>)->RetainedWorkOutcome<T,E>{match self.run(grant,maximum,|effect|RetainedWorkPoll::Complete(operation(effect))).0{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>unreachable!("a synchronous closer completes in its own original action")}}
 /// 🧵️ Lends the same actual Source dispatch alongside its original effect.
 pub fn run_with_source<T,E>(&mut self,grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>,OriginalSourceTurnWitness<'_>)->RetainedWorkPoll<T,E>)->(RetainedWorkPoll<T,E>,Option<usize>){
  if let Some(selected)=self.selected{assert_eq!(selected,(grant,maximum),"pending fixture action cannot change its original grant or work bound")}else{assert!(!self.marker_pending);assert!(self.admitted.is_none(),"original Work verdict must be inspected");let available=self.wallet.remaining();assert!(grant.maximum_items<=available.maximum_items&&grant.maximum_copy_bytes<=available.maximum_copy_bytes&&grant.maximum_capacity_bytes<=available.maximum_capacity_bytes&&grant.maximum_release_bytes<=available.maximum_release_bytes&&grant.maximum_depth<=available.maximum_depth,"original fixture grant {grant:?} exceeds its finite Source stock {available:?}; derive it with Wallet::within or from a quote");assert!(u128::from(maximum)<=self.wallet.work);self.marker_pending=true;self.selected=Some((grant,maximum));}
  let witness=self.turn.witness();let mut context=EffectWorkContext{source:&self.source,turn:&self.turn,remaining:&self.wallet.work};let actual=&mut self.actual;let action=&mut self.action;let partial=&mut self.partial;let state=self.state.take();
  let (result,performed,state,admitted)=self.work.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork{state,recipient:Some(&mut loan)};if action.is_none(){work.begin_turn();assert_eq!(work.prepare_for_action(maximum,action).unwrap(),Some(true))}let mut receipt=None;work.issue_performed_for_action(*action,&mut receipt).unwrap();let before=OriginalWorkSink::observed_work(receipt.as_ref().unwrap());let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut effect=RetainedAllocationEffect::new(grant,maximum,actual,receipt.as_mut().unwrap());operation(&mut effect,witness)}));let performed=OriginalWorkSink::observed_work(receipt.as_ref().unwrap()).checked_sub(before).expect("original receipt regressed");work.claim_performed_for_action(*action,&mut receipt).unwrap();if work.partial_pending_for_action(*action).unwrap(){assert!(work.settle_partial_for_action_into(*action,partial).unwrap());let outcome=partial.take().expect("fixture Source partial reply");assert_eq!(outcome.delta(),performed);assert!(outcome.source_refusal().is_none());}let mut admitted=None;if matches!(&result,Ok(RetainedWorkPoll::Complete(_))){let total=work.performed_total_for_action(*action).unwrap();if total==0&&!work.performed_seen_for_action(*action).unwrap(){work.cancel_for_action(action).unwrap()}else{let mut proof=None;admitted=Some(work.commit_for_action(total,*action,&mut proof).unwrap());work.finish_for_action(&mut proof,action).unwrap()}}(result,performed,work.state,admitted)}).unwrap();self.state=state;self.admitted=admitted;self.wallet.work=self.wallet.work.checked_sub(performed).expect("fixture work stock exhausted");
  match result{Ok(turn)=>{let reported=match &turn{RetainedWorkPoll::Pending{work}=>*work,RetainedWorkPoll::Complete(turn)=>turn.work};assert_eq!(reported,performed,"reported work differs from original performed receipt");if matches!(&turn,RetainedWorkPoll::Complete(_)){assert!(!self.work.has_live_actions());self.selected=None;self.marker_pending=false;(turn,self.actual.take())}else{(turn,None)}},Err(payload)=>std::panic::resume_unwind(payload)}
 }
 /// 🪙️ Debits the work of a turn that ran under the caller's own persistent decoder session.
 pub fn debit_work(&mut self,work:u128){self.wallet.work=self.wallet.work.checked_sub(work).expect("fixture work stock exhausted")}
 /// 🧾️ Posts independently observed physical progress after the action has debited its work.
 pub fn post(&mut self,progress:RetainedCloneProgress,grant:RetainedCloneGrant,heap:(usize,usize)){self.wallet.post(progress,0,grant,heap)}
}

#[cfg(test)]
mod effect_bank_tests{
 use super::*;
 /// 🧪️ A single original pending action keeps its Source, receipt and finite wallet through unwind.
 #[test]fn effect_bank_keeps_original_work_across_unwind(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let work=fixture["work"].as_array().unwrap();let grant=bank.loan(1,8);let first=work[0].as_u64().unwrap();let (turn,actual)=bank.run(grant,5,|effect|{assert!(effect.work_source_turn().is_some());assert!(effect.performed(first).unwrap());RetainedWorkPoll::<(),ValueError>::Pending{work:u128::from(first)}});assert!(matches!(turn,RetainedWorkPoll::Pending{..}));assert_eq!(actual,None);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(grant,5,|effect|->RetainedWorkPoll<(),ValueError>{assert!(effect.performed(work[1].as_u64().unwrap()).unwrap());panic!("original fixture producer interrupted")})));assert!(interrupted.is_err());assert_eq!(bank.actual(),None);let last=work[2].as_u64().unwrap();let (turn,actual)=bank.run(grant,5,|effect|{assert!(effect.performed(last).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:u128::from(last)})});assert!(matches!(turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));assert_eq!(bank.wallet().remaining_work(),0);}
 /// 🧵️ The actual dispatch witness remains bound to the same original pending effect.
 #[test]fn effect_bank_lends_same_source_through_pending(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let expected=bank.source_witness().identity();let grant=bank.loan(1,8);let mut first=None;let (pending,_)=bank.run_with_source(grant,2,|effect,turn|{assert_eq!(turn.identity(),expected);assert_eq!(effect.work_source_turn(),Some(turn.identity()));first=Some(turn.identity());assert!(effect.performed(1).unwrap());RetainedWorkPoll::<(),ValueError>::Pending{work:1}});assert!(matches!(pending,RetainedWorkPoll::Pending{work:1}));assert_eq!(bank.source_witness().identity(),expected);let (complete,_)=bank.run_with_source(grant,2,|effect,turn|{assert_eq!(Some(turn.identity()),first);assert_eq!(effect.work_source_turn(),first);assert!(effect.performed(1).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:1})});assert!(matches!(complete,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(bank.take_admitted(),Some(true));}
 /// 🔁️ A later action quotes only the finite work still in its original wallet.
 #[test]fn effect_bank_reuses_remaining_stock_without_double_charge(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));for units in [2u64,3]{let grant=bank.loan(1,8);let (turn,actual)=bank.run(grant,units,|effect|{assert!(effect.performed(units).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:u128::from(units)})});assert!(matches!(turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));}assert_eq!(bank.wallet().remaining_work(),0);}

 /// 🔒️ Pending keeps the exact original physical and work authority.
 #[test]fn effect_bank_pending_rejects_changed_original_grant(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();assert_eq!(fixture["rejectChangedGrant"],true);let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let grant=bank.loan(1,8);let (pending,_)=bank.run(grant,2,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::<(),ValueError>::Pending{work:1}});assert!(matches!(pending,RetainedWorkPoll::Pending{..}));let foreign=RetainedCloneGrant{maximum_items:0,..grant};let attempt=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(foreign,2,|_|->RetainedWorkPoll<(),ValueError>{panic!("foreign producer must not run")})));assert!(attempt.is_err());let (completed,_)=bank.run(grant,2,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:1})});assert!(matches!(completed,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(bank.take_admitted(),Some(true));}

 #[test]fn explicit_zero_work_still_settles_the_original_source_receipt(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let grant=bank.loan(1,8);let (turn,actual)=bank.run(grant,0,|effect|{assert!(effect.performed(0).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:0})});assert!(matches!(turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(()),..})));assert_eq!(actual,None);assert_eq!(bank.wallet().remaining_work(),fixture["zero"]["remainingWork"].as_u64().unwrap());assert_eq!(bank.take_admitted(),Some(true));let (turn,_)=bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:1})});assert!(matches!(turn,RetainedWorkPoll::Complete(_)));assert_eq!(bank.take_admitted(),Some(true));}


 #[test]fn settled_effect_bank_returns_only_its_original_remaining_wallet(){
  let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let law=&fixture["walletReturn"];let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let grant=bank.loan(1,8);let maximum=law["spent"].as_u64().unwrap();
  let (pending,_)=bank.run(grant,maximum,|effect|{assert!(effect.performed(1).unwrap());RetainedWorkPoll::<(),ValueError>::Pending{work:1}});assert!(matches!(pending,RetainedWorkPoll::Pending{..}));assert!(bank.has_pending_action());assert_eq!(law["pendingDenied"],true);bank=match bank.into_wallet(){Err(bank)=>bank,Ok(_)=>panic!("pending action surrendered its actual wallet")};
  let (complete,actual)=bank.run(grant,maximum,|effect|{assert!(effect.performed(maximum-1).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:u128::from(maximum-1)})});assert!(matches!(complete,RetainedWorkPoll::Complete(_)));assert_eq!(actual,None);assert!(!bank.has_pending_action());assert!(!bank.is_idle());assert_eq!(law["uninspectedDenied"],true);bank=match bank.into_wallet(){Err(bank)=>bank,Ok(_)=>panic!("uninspected admission surrendered its actual wallet")};assert_eq!(bank.take_admitted(),Some(true));assert!(bank.is_idle());let wallet=bank.into_wallet().ok().expect("settled original wallet");assert_eq!(wallet.work,u128::from(law["remaining"].as_u64().unwrap()))
 }

}

#[cfg(test)]
mod grant_axes_tests{
 use super::*;
 #[test]
 fn effect_bank_rejects_excessive_original_grant_before_producer_entry(){
  let law:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/axes.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let before=bank.wallet().remaining();let calls=std::cell::Cell::new(0);
  for row in law["refused"].as_array().unwrap(){let mut grant=bank.loan(2,8);let requested=row["request"].as_u64().unwrap()as usize;match row["axis"].as_str().unwrap(){"items"=>grant.maximum_items=requested,"copyBytes"=>grant.maximum_copy_bytes=requested,"capacityBytes"=>grant.maximum_capacity_bytes=requested,"releaseBytes"=>grant.maximum_release_bytes=requested,"depth"=>grant.maximum_depth=requested,_=>unreachable!()};let attempt=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(grant,0,|_|{calls.set(calls.get()+1);RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:0})})));assert!(attempt.is_err(),"excessive original axis entered producer: {}",row["axis"]);assert_eq!(calls.get(),law["producerCalls"].as_u64().unwrap());assert_eq!(bank.wallet().remaining(),before);assert_eq!(bank.wallet().remaining_work(),law["remainingWork"].as_u64().unwrap());assert_eq!(bank.is_idle(),law["idle"].as_bool().unwrap());assert_eq!(bank.actual,None);}
 }
}
